LESSON_DB.history.m2 = {
  0: {emoji:"🧊", subtitle:"Grade 12 · How allies became enemies after 1945",
    illusText:"The Berlin Wall went up in 1961 and fell in 1989 — the Cold War in concrete.",
    hook:{title:"A wall through a city", body:"Imagine waking up to find a wall built through the middle of your township, separating you from your cousins, your school and your job. That happened in Berlin in August 1961. The <strong>Berlin Wall</strong> divided the city for 28 years until 9 November 1989. It was the most visible symbol of the <strong>Cold War</strong> — a global rivalry that even shaped South Africa's history."},
    intro:"The <strong>Cold War</strong> (1945–1991) was a conflict between the <strong>USA</strong> (capitalism, democracy) and the <strong>USSR</strong> (communism, one-party state). They never fought each other directly — hence “cold” — but competed through alliances, propaganda, an arms race and proxy wars. After the Second World War, the Yalta and Potsdam conferences (1945) failed to settle Europe's future. Churchill warned of an <strong>“Iron Curtain”</strong> (1946). The USA's <strong>Truman Doctrine</strong> (containment) and <strong>Marshall Plan</strong> (1947) aimed to stop communism spreading. The <strong>Berlin Blockade</strong> (1948–49) led to the formation of <strong>NATO</strong> (1949); the Soviet bloc formed the <strong>Warsaw Pact</strong> (1955).",
    concepts:[
      {t:"green", title:"⚖️ Two ideologies", body:"Capitalism: private ownership and markets. Communism: state ownership and a planned economy. Each feared the other would spread."},
      {t:"teal", title:"🧱 Containment", body:"US policy to stop communism spreading, through aid (Marshall Plan), alliances (NATO) and, at times, war."},
      {t:"gold", title:"☢️ Arms race", body:"Both sides built nuclear weapons — mutually assured destruction made direct war too dangerous."},
    ],
    examples:[
      {title:"Why “cold”?", body:"Why is it called the Cold War?", answer:"The superpowers <strong>never fought each other directly</strong>; they competed through proxy wars, propaganda and an arms race."},
      {title:"Marshall Plan", body:"What was the aim of the Marshall Plan?", answer:"To give <strong>economic aid to rebuild Western Europe</strong>, so poverty would not push countries towards communism."},
      {title:"Berlin Blockade", body:"How did the West respond to the 1948 Berlin Blockade?", answer:"With the <strong>Berlin Airlift</strong>, flying supplies into West Berlin until the USSR lifted the blockade in 1949."},
    ],
    mistakes:["Saying the USA and USSR fought each other directly.","Mixing up the Truman Doctrine (political) and Marshall Plan (economic).","Writing narrative without explaining causes."],
    callout:{title:"Why it matters here", body:"The apartheid government used fear of communism (“rooi gevaar”) to justify repression and win Western support. The Cold War is part of South African history."},
    activity:"Create a timeline of the origins of the Cold War from 1945 to 1955 with six events.",
    activityAnswer:"1945 Yalta and Potsdam · 1946 Iron Curtain speech · 1947 Truman Doctrine and Marshall Plan · 1948–49 Berlin Blockade and Airlift · 1949 NATO formed · 1955 Warsaw Pact formed.",
    examTip:"Cold War essays need a clear line of argument (e.g. “Both superpowers were responsible…”) supported with dated evidence.",
    keyterms:[{w:"Cold War",d:"Rivalry between the USA and USSR, 1945–1991"},{w:"Containment",d:"US policy of stopping the spread of communism"},{w:"Proxy war",d:"A war fought by others on behalf of the superpowers"}],
    quiz:[
      {q:"The Marshall Plan provided:",opts:["Nuclear weapons","Economic aid to Europe","Soldiers for Korea","A wall in Berlin"],a:1,et:"Announced in 1947."},
      {q:"NATO was formed in:",opts:["1945","1949","1955","1961"],a:1,et:"After the Berlin Blockade."},
      {q:"The Berlin Wall fell in:",opts:["1961","1975","1989","1994"],a:2,et:"9 November 1989."},
    ],
    conclusion:"The Cold War divided the world into two camps. Its fears and rivalries reached all the way to southern Africa."},

  1: {emoji:"🚀", subtitle:"Grade 12 · Hot wars and near-misses",
    illusText:"In October 1962, the world came closer to nuclear war than ever before — for 13 days.",
    hook:{title:"South Africans in Korea", body:"Few South Africans know that the South African Air Force's 2 Squadron — the “Flying Cheetahs” — fought in the <strong>Korean War</strong> (1950–1953) on the side of the United Nations. The Cold War wasn't only a European affair: it became “hot” in Korea, and nearly turned nuclear over Cuba in 1962."},
    intro:"<strong>Korea</strong> was divided at the <strong>38th parallel</strong> after 1945: the communist North (backed by the USSR and China) and the capitalist South (backed by the USA). In June 1950, North Korea invaded the South. UN forces led by the USA pushed back; China joined in to support the North. An <strong>armistice</strong> was signed in July 1953, roughly at the original border — Korea remains divided today. In the <strong>Cuban Missile Crisis</strong> (October 1962), the USA discovered Soviet nuclear missiles in Cuba, 150 km from Florida. After 13 tense days, Khrushchev agreed to remove the missiles; the USA promised not to invade Cuba and secretly agreed to remove its missiles from Turkey.",
    concepts:[
      {t:"green", title:"🇰🇷 Korea", body:"A proxy war that ended in stalemate — and a divided peninsula that still exists."},
      {t:"teal", title:"🇨🇺 Cuba", body:"Brinkmanship: pushing to the edge of war to force the other side to back down."},
      {t:"gold", title:"☎️ After the crisis", body:"A direct hotline was set up between Washington and Moscow in 1963 to prevent misunderstandings."},
    ],
    examples:[
      {title:"Proxy war", body:"Why is Korea called a proxy war?", answer:"The superpowers <strong>supported opposite sides</strong> instead of fighting each other directly."},
      {title:"Why missiles in Cuba?", body:"Why did the USSR place missiles in Cuba?", answer:"To <strong>protect Cuba</strong> after the US-backed Bay of Pigs invasion (1961) and to balance US missiles in Turkey."},
      {title:"Resolution", body:"How was the Cuban Missile Crisis resolved?", answer:"The USSR <strong>removed its missiles</strong>; the USA promised not to invade Cuba and later removed missiles from Turkey."},
    ],
    mistakes:["Saying the Korean War ended in a peace treaty — it ended in an armistice.","Forgetting the USA's secret deal on Turkey.","Not linking events to Cold War ideas like containment and brinkmanship."],
    callout:{title:"Still divided", body:"North and South Korea are still technically at war — a reminder that Cold War decisions can last generations."},
    activity:"Write a short news report from 28 October 1962 announcing the end of the Cuban Missile Crisis.",
    activityAnswer:"A good report gives the date, explains the missiles and the US blockade (“quarantine”), states Khrushchev's agreement to remove them and the US pledge not to invade Cuba, and notes the world's relief.",
    examTip:"Source questions on Cuba often use cartoons — explain the symbols and the cartoonist's message.",
    keyterms:[{w:"38th parallel",d:"The line dividing North and South Korea"},{w:"Armistice",d:"An agreement to stop fighting"},{w:"Brinkmanship",d:"Pushing a crisis to the edge of war to gain advantage"}],
    quiz:[
      {q:"The Korean War ended with:",opts:["A peace treaty","An armistice","The fall of Seoul","Nuclear war"],a:1,et:"July 1953 — no peace treaty."},
      {q:"The Cuban Missile Crisis took place in:",opts:["1950","1962","1975","1989"],a:1,et:"October 1962."},
      {q:"The SAAF squadron in Korea was nicknamed the:",opts:["Springboks","Flying Cheetahs","Proteas","Bafana Bafana"],a:1,et:"2 Squadron."},
    ],
    conclusion:"Korea and Cuba show the Cold War at its most dangerous — hot war in one place, nuclear brinkmanship in another."},

  2: {emoji:"🌍", subtitle:"Grade 12 · Africa wins its independence",
    illusText:"In 1960, the “Year of Africa”, seventeen African countries became independent.",
    hook:{title:"The “Wind of Change” — in Cape Town", body:"On 3 February 1960, British Prime Minister Harold Macmillan stood in South Africa's Parliament in Cape Town and said: “The wind of change is blowing through this continent.” He was warning the apartheid government that colonial rule in Africa was ending. That same year, seventeen African countries became independent. Ghana had led the way in 1957."},
    intro:"<strong>Decolonisation</strong> is the process by which colonies gained independence. After the Second World War, colonial powers were weakened, African soldiers who had fought abroad returned demanding rights, and nationalist movements grew. <strong>Ghana</strong> (1957), led by <strong>Kwame Nkrumah</strong>, was the first sub-Saharan colony to win independence. In <strong>1960</strong> — the “Year of Africa” — seventeen countries followed. Tanganyika (later Tanzania) became independent in 1961 under <strong>Julius Nyerere</strong>, who introduced <strong>Ujamaa</strong> (African socialism). The <strong>Organisation of African Unity (OAU)</strong> was formed in 1963. New states faced challenges: borders drawn by colonisers, economies built to export raw materials, and Cold War pressures.",
    concepts:[
      {t:"green", title:"🔥 Causes", body:"Weakened colonial powers, nationalist leaders, educated elites, returning soldiers and international support (UN, superpowers)."},
      {t:"teal", title:"🏛️ New states", body:"Leaders had to build national unity, schools, health systems and economies — often with little money and colonial borders."},
      {t:"gold", title:"🌾 Ujamaa", body:"Nyerere's policy of villagisation and self-reliance: it improved literacy but agricultural production suffered."},
    ],
    examples:[
      {title:"First to independence", body:"Which country led sub-Saharan Africa to independence?", answer:"<strong>Ghana</strong> in 1957, led by Kwame Nkrumah."},
      {title:"Ujamaa", body:"Give one success and one failure of Ujamaa.", answer:"Success: <strong>higher literacy</strong> and national unity. Failure: <strong>falling farm production</strong> after forced villagisation."},
      {title:"Colonial borders", body:"Why did colonial borders cause problems?", answer:"They were drawn by Europeans and <strong>split or combined ethnic groups</strong>, contributing to conflict."},
    ],
    mistakes:["Saying all African countries became independent at the same time.","Ignoring the economic challenges new states inherited.","Writing about leaders without evaluating their policies."],
    callout:{title:"South Africa's position", body:"While the rest of Africa was decolonising, South Africa was tightening apartheid. Independent African states later supported the liberation movements and hosted exiles."},
    activity:"Compare Ghana and Tanzania after independence: leader, year, key policy and one challenge.",
    activityAnswer:"Ghana: Nkrumah, 1957, Pan-Africanism and industrialisation, debt and a one-party state. Tanzania: Nyerere, 1961, Ujamaa, falling agricultural output.",
    examTip:"In essays on independent Africa, evaluate success and failure with evidence — CAPS rewards a balanced argument.",
    keyterms:[{w:"Decolonisation",d:"Colonies gaining independence"},{w:"Ujamaa",d:"Nyerere's policy of African socialism in Tanzania"},{w:"OAU",d:"Organisation of African Unity, formed in 1963"}],
    quiz:[
      {q:"The first sub-Saharan country to gain independence was:",opts:["Kenya","Ghana","Tanzania","Congo"],a:1,et:"In 1957 under Nkrumah."},
      {q:"Macmillan's “Wind of Change” speech was given in:",opts:["London","Accra","Cape Town","Nairobi"],a:2,et:"3 February 1960."},
      {q:"Ujamaa was introduced by:",opts:["Nkrumah","Nyerere","Lumumba","Mobutu"],a:1,et:"In Tanzania."},
    ],
    conclusion:"Independence was won quickly; building strong nations proved much harder. Both stories matter."},

  3: {emoji:"🇨🇩", subtitle:"Grade 12 · Hope, crisis and Cold War in the Congo",
    illusText:"In 2022, Belgium returned a tooth — all that remained of Patrice Lumumba.",
    hook:{title:"A tooth returned after 61 years", body:"In June 2022, Belgium handed a gold-capped tooth to Patrice Lumumba's family in a ceremony in Brussels. It was all that was left of the Congo's first Prime Minister, murdered in 1961 with Belgian involvement, his body destroyed. Lumumba's story shows how independence, Cold War rivalry and foreign interests collided in the Congo."},
    intro:"The <strong>Belgian Congo</strong> became independent on <strong>30 June 1960</strong>, with very little preparation: few Congolese had been allowed university education. <strong>Patrice Lumumba</strong> became Prime Minister. Within days, the army mutinied and the mineral-rich province of <strong>Katanga</strong> seceded under Moise Tshombe, backed by Belgian and mining interests. Lumumba asked the UN and then the USSR for help, so the West saw him as a communist threat. He was overthrown, captured and <strong>killed on 17 January 1961</strong>. Army chief <strong>Joseph Mobutu</strong> took power in 1965, renamed the country Zaire and ruled as a dictator until 1997, supported by the West as an anti-communist ally.",
    concepts:[
      {t:"green", title:"⚠️ Unprepared independence", body:"Belgium left few trained administrators and kept control of the economy, setting the Congo up for crisis."},
      {t:"teal", title:"💎 Minerals and secession", body:"Katanga's copper and cobalt made it valuable; foreign mining interests backed its secession."},
      {t:"gold", title:"🧊 Cold War pressure", body:"Lumumba's appeal to the USSR made Western powers support his removal and later back Mobutu."},
    ],
    examples:[
      {title:"Why did the crisis start?", body:"Give two causes of the Congo Crisis.", answer:"<strong>Lack of preparation</strong> for independence and the <strong>secession of Katanga</strong> (plus the army mutiny)."},
      {title:"Cold War link", body:"How did the Cold War affect Lumumba?", answer:"His request for <strong>Soviet help</strong> made the USA and Belgium see him as a threat, contributing to his overthrow and murder."},
      {title:"Mobutu", body:"Why did the West support Mobutu?", answer:"He was <strong>anti-communist</strong> and kept the Congo's minerals open to Western companies."},
    ],
    mistakes:["Blaming the crisis only on Congolese leaders and ignoring Belgium's role.","Forgetting the Cold War dimension.","Getting dates wrong: independence 1960, Lumumba killed 1961, Mobutu's coup 1965."],
    callout:{title:"Your phone and the Congo", body:"Cobalt from the DRC is used in phone and electric-car batteries. Who controls the Congo's minerals is still a global question."},
    activity:"Write a short obituary for Patrice Lumumba, explaining his achievements and the forces against him.",
    activityAnswer:"A strong obituary mentions his role as the Congo's first elected Prime Minister, his speech on Independence Day criticising colonialism, the Katanga secession, Cold War pressures and his murder in January 1961.",
    examTip:"In source questions, identify Belgian, American, Soviet and Congolese perspectives and explain how each source's origin affects its view.",
    keyterms:[{w:"Secession",d:"A region breaking away from a country"},{w:"Katanga",d:"Mineral-rich province that seceded in 1960"},{w:"Kleptocracy",d:"Rule by leaders who steal the country's wealth"}],
    quiz:[
      {q:"The Congo became independent from:",opts:["France","Belgium","Portugal","Britain"],a:1,et:"On 30 June 1960."},
      {q:"Which province seceded in 1960?",opts:["Kinshasa","Katanga","Kivu","Kasai only"],a:1,et:"Led by Moise Tshombe."},
      {q:"Mobutu renamed the Congo:",opts:["Zaire","Zambia","Zimbabwe","Angola"],a:0,et:"He ruled until 1997."},
    ],
    conclusion:"The Congo's independence was hijacked by minerals and the Cold War. Lumumba's story is still being reckoned with today."},

  4: {emoji:"🇦🇴", subtitle:"Grade 12 · South Africa's war on the border",
    illusText:"The battles around Cuito Cuanavale (1987–88) helped bring Namibia its independence.",
    hook:{title:"The “border war” your grandfather remembers", body:"Many older South African men were conscripted and sent to the “border” — northern Namibia and southern Angola. Others fought on the opposite side, in MK or with SWAPO. Angola became one of the hottest battlegrounds of the Cold War in Africa, with South African, Cuban and Soviet involvement. Its ending in 1988 helped open the way to Namibian independence — and to change in South Africa."},
    intro:"Angola became independent from <strong>Portugal</strong> on <strong>11 November 1975</strong> after a coup in Lisbon (1974) ended Portugal's colonial wars. Three movements fought for control: the <strong>MPLA</strong> (backed by the USSR and Cuba), and <strong>UNITA</strong> and the <strong>FNLA</strong> (backed by the USA and South Africa). South Africa invaded in 1975 (Operation Savannah) but withdrew; the MPLA took power. The war continued for over a decade. The battles around <strong>Cuito Cuanavale</strong> (1987–88) ended in a stalemate that both sides claimed as a victory. The <strong>New York Accords</strong> (December 1988) led to Cuban withdrawal from Angola and South African withdrawal from Namibia, which became independent on <strong>21 March 1990</strong>.",
    concepts:[
      {t:"green", title:"🧩 A three-way civil war", body:"MPLA vs UNITA vs FNLA — each supported by outside powers."},
      {t:"teal", title:"🌐 Foreign involvement", body:"Cuba sent tens of thousands of troops; the USSR sent weapons; the USA and South Africa backed UNITA."},
      {t:"gold", title:"🕊️ The settlement", body:"The New York Accords linked Cuban withdrawal from Angola to Namibian independence."},
    ],
    examples:[
      {title:"Why did SA intervene?", body:"Why did the South African government get involved in Angola?", answer:"To stop a <strong>communist-backed government</strong> on its region's border and to prevent SWAPO and the ANC using Angola as a base."},
      {title:"Cuito Cuanavale", body:"Why is Cuito Cuanavale significant?", answer:"The military <strong>stalemate</strong> pushed all sides to negotiate, leading to the New York Accords and Namibian independence."},
      {title:"Cold War link", body:"How was Angola a Cold War conflict?", answer:"The <strong>superpowers and their allies backed opposing movements</strong> — a proxy war."},
    ],
    mistakes:["Saying one side clearly “won” at Cuito Cuanavale — historians debate this.","Forgetting Namibia's independence as an outcome.","Ignoring the Angolan people's own civil war, which continued until 2002."],
    callout:{title:"Freedom Park", body:"Freedom Park in Pretoria honours Cuban soldiers who died in Angola alongside South African liberation fighters — a sign of how differently this war is remembered."},
    activity:"Make a table of the three Angolan movements: leader, ideology and foreign backers.",
    activityAnswer:"MPLA: Agostinho Neto, Marxist, USSR and Cuba. UNITA: Jonas Savimbi, anti-communist, USA and South Africa. FNLA: Holden Roberto, nationalist, USA and Zaire.",
    examTip:"Explain how events in Angola connect to South Africa's own transition: the end of the war, Namibian independence and the end of the Cold War all helped make 1990 possible.",
    keyterms:[{w:"MPLA",d:"Angolan movement backed by the USSR and Cuba"},{w:"UNITA",d:"Angolan movement backed by the USA and South Africa"},{w:"New York Accords",d:"1988 agreement leading to Namibian independence"}],
    quiz:[
      {q:"Angola became independent from:",opts:["Belgium","Portugal","Britain","Spain"],a:1,et:"On 11 November 1975."},
      {q:"The MPLA was backed by:",opts:["The USA and SA","The USSR and Cuba","Britain","China only"],a:1,et:"Cuba sent troops."},
      {q:"Namibia became independent in:",opts:["1975","1988","1990","1994"],a:2,et:"21 March 1990."},
    ],
    conclusion:"Angola was where the Cold War met southern Africa's liberation struggles. Its end helped free Namibia and opened the door to change at home."},

  5: {emoji:"🛡️", subtitle:"Grade 12 · “Total onslaught” and the end of the Cold War",
    illusText:"When the Soviet Union collapsed, the apartheid government lost its favourite excuse.",
    hook:{title:"The “rooi gevaar”", body:"For decades, the National Party told white South Africans they faced a <strong>“rooi gevaar”</strong> (red danger) — a communist plot to take over the country. Opponents of apartheid were labelled communists, and Western governments often looked the other way because South Africa claimed to be an anti-communist ally. When the Berlin Wall fell in 1989, that argument fell with it."},
    intro:"The apartheid government used the Cold War to justify repression. The <strong>Suppression of Communism Act</strong> (1950) was used against many opponents. Under P.W. Botha (1978–1989), the government claimed a <strong>“total onslaught”</strong> and answered with a <strong>“total strategy”</strong>: military build-up, conscription, cross-border raids, states of emergency (1985–1990) and some reforms to win support. The <strong>collapse of the USSR</strong> (1989–1991) changed everything: the communist threat disappeared, the ANC lost a major backer, and Western countries increased pressure through sanctions. F.W. de Klerk, who became president in 1989, judged that it was time to negotiate.",
    concepts:[
      {t:"green", title:"🔴 Anti-communism as a tool", body:"Labelling opponents as communists justified banning, detention and Western support."},
      {t:"teal", title:"🪖 Total strategy", body:"Botha's response combined force (army, police, emergencies) with limited reforms (e.g. the 1983 Tricameral Parliament)."},
      {t:"gold", title:"🧱 1989 changes", body:"The fall of the Berlin Wall removed the communist threat, making negotiation easier for both sides."},
    ],
    examples:[
      {title:"Total onslaught", body:"What did the government mean by “total onslaught”?", answer:"The claim that South Africa faced a <strong>coordinated communist attack</strong> from inside and outside the country."},
      {title:"Why negotiate in 1990?", body:"How did the end of the Cold War encourage negotiations?", answer:"The <strong>communist threat disappeared</strong>, Western support for apartheid ended, and the ANC lost Soviet backing — both sides had reasons to talk."},
      {title:"Sanctions", body:"How did international pressure contribute?", answer:"<strong>Sanctions and disinvestment</strong> in the 1980s damaged the economy and isolated the government."},
    ],
    mistakes:["Treating the Cold War and South African history as separate topics.","Saying De Klerk acted only from moral change — many pressures were involved.","Forgetting internal resistance (UDF, COSATU, mass protests) as a cause of change."],
    callout:{title:"Many causes", body:"Change in 1990 came from internal resistance, economic crisis, sanctions, the end of the Cold War and leadership choices — strong essays weigh them."},
    activity:"List five reasons the apartheid government decided to negotiate in 1990. Rank them and justify your top choice.",
    activityAnswer:"Internal resistance and ungovernability; economic decline and sanctions; end of the Cold War; military stalemate in Angola; leadership of De Klerk and Mandela. Any ranking is acceptable if justified with evidence.",
    examTip:"For “Why did…” essays, structure by cause and weigh their importance — markers reward argument, not lists.",
    keyterms:[{w:"Total onslaught",d:"The apartheid government's claim of a communist threat"},{w:"Total strategy",d:"Botha's military and political response"},{w:"Sanctions",d:"International penalties to pressure a government"}],
    quiz:[
      {q:"“Rooi gevaar” means:",opts:["Red danger","Total strategy","Freedom now","Rainbow nation"],a:0,et:"Fear of communism."},
      {q:"“Total strategy” is associated with:",opts:["Mandela","P.W. Botha","Verwoerd","Sobukwe"],a:1,et:"President 1978–1989 (as PM then State President)."},
      {q:"The end of the Cold War made negotiation easier because:",opts:["The communist threat disappeared","Apartheid laws became stronger","The ANC won a war","Sanctions began"],a:0,et:"The government's main excuse fell away."},
    ],
    conclusion:"The Cold War gave apartheid an excuse; its end took that excuse away. South Africa's transition was part of a changing world."},
};

// ─── Module 3: South Africa's Democracy ─────────────────────────────────────
LESSON_DB.history.m3 = {
  0: {emoji:"🔓", subtitle:"Grade 12 · 2 February 1990 and the release of Mandela",
    illusText:"On 11 February 1990, Nelson Mandela walked out of Victor Verster Prison after 27 years.",
    hook:{title:"The walk out of prison", body:"On <strong>11 February 1990</strong>, millions watched on television as Nelson Mandela walked out of Victor Verster Prison near Paarl, fist raised, after 27 years in jail. Nine days earlier, President F.W. de Klerk had shocked Parliament — and the world — by announcing the unbanning of the ANC, PAC, SACP and other organisations. South Africa's road to democracy had begun."},
    intro:"In his speech to Parliament on <strong>2 February 1990</strong>, <strong>F.W. de Klerk</strong> unbanned the ANC, PAC, SACP and dozens of other organisations, announced the release of political prisoners including <strong>Nelson Mandela</strong>, lifted restrictions on the media and partly lifted the state of emergency. Reasons included economic decline, sanctions, ongoing resistance, the end of the Cold War, and secret talks between Mandela and government officials from 1985. Mandela was released on <strong>11 February 1990</strong>. The <strong>Groote Schuur Minute</strong> (May 1990) and <strong>Pretoria Minute</strong> (August 1990, when the ANC suspended the armed struggle) started formal talks.",
    concepts:[
      {t:"green", title:"📢 The announcement", body:"Unbanning, releases and lifting restrictions — a dramatic break with decades of NP policy."},
      {t:"teal", title:"🤫 Secret talks", body:"From 1985, Mandela met government officials in prison. Exiled ANC leaders also met South African businesspeople and academics."},
      {t:"gold", title:"🤝 First agreements", body:"Groote Schuur and Pretoria Minutes removed obstacles to negotiations."},
    ],
    examples:[
      {title:"Why unban in 1990?", body:"Give three reasons for De Klerk's announcement.", answer:"<strong>Economic decline and sanctions</strong>, <strong>continuing mass resistance</strong>, and the <strong>end of the Cold War</strong>."},
      {title:"Pretoria Minute", body:"What did the ANC agree to in the Pretoria Minute?", answer:"To <strong>suspend the armed struggle</strong> to make negotiations possible."},
      {title:"Significance", body:"Why was 2 February 1990 a turning point?", answer:"It ended the ban on liberation movements and made <strong>negotiations</strong> possible."},
    ],
    mistakes:["Mixing up the dates: speech 2 February, release 11 February 1990.","Giving all the credit to one person.","Forgetting the secret talks before 1990."],
    callout:{title:"Two Nobel laureates", body:"Mandela and De Klerk shared the Nobel Peace Prize in 1993 for their roles in ending apartheid peacefully."},
    activity:"Read (or listen to) part of Mandela's speech from Cape Town City Hall on 11 February 1990. Identify two promises or messages in it.",
    activityAnswer:"Examples: he committed himself to serving the people; he called for continued struggle and pressure until apartheid ended; he spoke of a negotiated settlement and a non-racial democracy.",
    examTip:"When evaluating sources such as speeches, consider the speaker's audience and purpose.",
    keyterms:[{w:"Unbanning",d:"Making banned organisations legal again"},{w:"Pretoria Minute",d:"1990 agreement in which the ANC suspended the armed struggle"},{w:"Political prisoner",d:"A person jailed for their political beliefs or actions"}],
    quiz:[
      {q:"De Klerk announced the unbanning of the ANC on:",opts:["2 February 1990","11 February 1990","27 April 1994","16 June 1976"],a:0,et:"In Parliament."},
      {q:"Mandela was released from:",opts:["Robben Island","Victor Verster Prison","Pollsmoor Prison","Sun City"],a:1,et:"Near Paarl, 11 February 1990."},
      {q:"In the Pretoria Minute, the ANC agreed to:",opts:["Join the NP","Suspend the armed struggle","Leave South Africa","Cancel elections"],a:1,et:"August 1990."},
    ],
    conclusion:"February 1990 opened a door that had been locked for decades. Walking through it would take four more difficult years."},

  1: {emoji:"🤝", subtitle:"Grade 12 · Talking through violence",
    illusText:"After Chris Hani's assassination in 1993, Mandela's televised call for calm kept the talks alive.",
    hook:{title:"Easter Saturday, 1993", body:"On <strong>10 April 1993</strong>, Chris Hani, leader of the SACP and hugely popular among young people, was shot dead outside his home in Boksburg by a right-wing extremist. The country was on the edge of civil war. That night Nelson Mandela — not yet president — went on national television to call for calm. The killing shocked negotiators into setting a date for elections. <strong>CODESA</strong> and the talks that followed nearly failed many times."},
    intro:"<strong>CODESA</strong> (Convention for a Democratic South Africa) began in <strong>December 1991</strong> with 19 parties. <strong>CODESA 2</strong> (May 1992) deadlocked, mainly over how large a majority would be needed to write the constitution. Violence threatened the process: the <strong>Boipatong massacre</strong> (June 1992), after which the ANC withdrew from talks; the <strong>Bisho massacre</strong> (September 1992); and political violence in KwaZulu-Natal and on the East Rand. The <strong>Record of Understanding</strong> (September 1992) restarted talks. Joe Slovo's <strong>“sunset clauses”</strong> proposed a Government of National Unity and job security for civil servants. After Hani's assassination, the <strong>Multi-Party Negotiating Forum</strong> set the election date: <strong>27 April 1994</strong>. An <strong>interim constitution</strong> was agreed in late 1993.",
    concepts:[
      {t:"green", title:"🧩 Deadlock", body:"The NP wanted minority protections and power-sharing; the ANC wanted majority rule."},
      {t:"teal", title:"🩸 Violence", body:"Massacres and assassinations threatened to derail negotiations — and sometimes pushed leaders back to the table."},
      {t:"gold", title:"🌅 Compromise", body:"Sunset clauses, a Government of National Unity and an interim constitution made agreement possible."},
    ],
    examples:[
      {title:"Why CODESA 2 failed", body:"What caused the deadlock at CODESA 2?", answer:"Disagreement over the <strong>majority needed to approve the new constitution</strong> and over power-sharing."},
      {title:"Sunset clauses", body:"What were the sunset clauses?", answer:"Compromises proposed by <strong>Joe Slovo</strong>: a temporary Government of National Unity and protection for civil servants' jobs."},
      {title:"Hani's death", body:"How did Hani's assassination affect negotiations?", answer:"It pushed negotiators to <strong>agree on an election date</strong> to prevent a slide into civil war."},
    ],
    mistakes:["Presenting negotiations as smooth and peaceful.","Forgetting that violence came from several sides, including state-linked “third force” actors.","Mixing up CODESA 1 (1991) and CODESA 2 (1992)."],
    callout:{title:"A model for the world", body:"South Africa's negotiated transition is studied around the world as an example of how enemies can agree on a shared future."},
    activity:"Create a timeline from December 1991 to April 1994 with at least six events in the negotiations.",
    activityAnswer:"Dec 1991 CODESA 1 · May 1992 CODESA 2 deadlock · June 1992 Boipatong · Sept 1992 Bisho and Record of Understanding · April 1993 Hani assassinated; Multi-Party Negotiating Forum · Nov 1993 interim constitution · 27 April 1994 election.",
    examTip:"Essays on negotiations should show both the obstacles (violence, deadlock) and how they were overcome (compromises, leadership).",
    keyterms:[{w:"CODESA",d:"Convention for a Democratic South Africa (1991–1992)"},{w:"Sunset clauses",d:"Compromises including a Government of National Unity"},{w:"Interim constitution",d:"Temporary constitution agreed in 1993"}],
    quiz:[
      {q:"Chris Hani was assassinated in:",opts:["1990","1992","1993","1994"],a:2,et:"10 April 1993."},
      {q:"The sunset clauses were proposed by:",opts:["Joe Slovo","F.W. de Klerk","Mangosuthu Buthelezi","P.W. Botha"],a:0,et:"An SACP leader."},
      {q:"CODESA 2 broke down in:",opts:["1991","1992","1993","1994"],a:1,et:"May 1992."},
    ],
    conclusion:"Democracy was negotiated through deadlock and bloodshed. Compromise and leadership kept the talks alive."},

  2: {emoji:"🗳️", subtitle:"Grade 12 · The day South Africans queued for freedom",
    illusText:"On 27 April 1994, millions of people queued for hours to vote for the first time.",
    hook:{title:"The longest queues in history", body:"On <strong>27 April 1994</strong>, South Africans of every race stood side by side in queues that stretched for kilometres. Grandmothers who had waited their whole lives to vote came in wheelchairs. Nelson Mandela voted at Ohlange High School in Inanda, near the grave of the ANC's first president, John Dube. That day is now <strong>Freedom Day</strong>."},
    intro:"South Africa's first democratic election was held from <strong>26 to 29 April 1994</strong>, with <strong>27 April</strong> the main voting day. About 19.7 million people voted. The <strong>ANC</strong> won about 62.6%, the <strong>NP</strong> 20.4% and the <strong>IFP</strong> 10.5%. The IFP joined only days before the vote, after last-minute negotiations. Under the interim constitution, a <strong>Government of National Unity</strong> was formed. <strong>Nelson Mandela</strong> was inaugurated as president on <strong>10 May 1994</strong>, with Thabo Mbeki and F.W. de Klerk as deputy presidents. Parliament then worked as the Constitutional Assembly to write the final Constitution.",
    concepts:[
      {t:"green", title:"🗳️ The vote", body:"One person, one vote — for the first time in South Africa's history."},
      {t:"teal", title:"🤝 GNU", body:"Parties with enough votes shared cabinet posts, easing fears during the transition."},
      {t:"gold", title:"🏛️ Inauguration", body:"Mandela's inauguration at the Union Buildings was attended by leaders from around the world."},
    ],
    examples:[
      {title:"Results", body:"Which three parties won the most votes?", answer:"<strong>ANC (about 62.6%)</strong>, NP (about 20.4%) and IFP (about 10.5%)."},
      {title:"Why GNU?", body:"Why was a Government of National Unity formed?", answer:"To <strong>reassure minorities and include major parties</strong> during the transition — a compromise from the negotiations."},
      {title:"Freedom Day", body:"Why is 27 April a public holiday?", answer:"It marks the <strong>first democratic election</strong> in 1994."},
    ],
    mistakes:["Saying the ANC won two-thirds — it won about 62.6%.","Mixing up election day (27 April) and inauguration (10 May).","Forgetting the IFP's late decision to participate."],
    callout:{title:"Your vote", body:"Voting is a right people died for. You can register to vote at 16 and vote from 18."},
    activity:"Ask someone who voted in 1994 to describe the day. Compare their memory with a news report or photograph from 1994.",
    activityAnswer:"Answers vary. A strong answer notes how memory and official records can agree or differ, and why oral history adds personal detail.",
    examTip:"Use precise figures and dates when writing about 1994: 27 April, 10 May, ANC about 62.6%.",
    keyterms:[{w:"Government of National Unity",d:"Power-sharing government formed after 1994"},{w:"Inauguration",d:"Ceremony when a leader takes office"},{w:"Freedom Day",d:"27 April — anniversary of the 1994 election"}],
    quiz:[
      {q:"South Africa's first democratic election day was:",opts:["16 June 1994","27 April 1994","10 May 1994","2 February 1990"],a:1,et:"Now Freedom Day."},
      {q:"The ANC won about:",opts:["42%","52%","62%","72%"],a:2,et:"About 62.6%."},
      {q:"Mandela was inaugurated on:",opts:["27 April 1994","10 May 1994","11 February 1990","10 December 1996"],a:1,et:"At the Union Buildings."},
    ],
    conclusion:"27 April 1994 was the day South Africa belonged to all who live in it — at least at the ballot box."},

  3: {emoji:"⚖️", subtitle:"Grade 12 · Truth, amnesty and reconciliation",
    illusText:"Archbishop Desmond Tutu chaired the TRC; at times he wept openly at the hearings.",
    hook:{title:"Testimony in a church hall", body:"In church halls and town halls across the country, from 1996, ordinary people stood up and told the <strong>Truth and Reconciliation Commission (TRC)</strong> what had happened to their loved ones. Some perpetrators confessed to murder and torture to apply for amnesty. Archbishop Desmond Tutu, who chaired the commission, sometimes broke down in tears. The TRC tried something new: healing a nation through truth."},
    intro:"The <strong>TRC</strong> was set up by the <strong>Promotion of National Unity and Reconciliation Act (1995)</strong> and chaired by <strong>Archbishop Desmond Tutu</strong>. Public hearings began in <strong>April 1996</strong>. It had three committees: <strong>Human Rights Violations</strong> (hearing victims), <strong>Amnesty</strong> (perpetrators could get amnesty if they made full disclosure of politically motivated crimes) and <strong>Reparation and Rehabilitation</strong> (recommending support for victims). About 7 000 people applied for amnesty; fewer than 1 000 received it. The final report was handed to President Mandela in <strong>October 1998</strong>. Critics argued that some perpetrators never came forward, prosecutions were rare and reparations were slow and small.",
    concepts:[
      {t:"green", title:"🗣️ Truth", body:"Victims' stories were heard publicly; families learned what happened to missing relatives."},
      {t:"teal", title:"📜 Amnesty", body:"Full disclosure of politically motivated crimes in exchange for freedom from prosecution — truth over punishment."},
      {t:"gold", title:"🩹 Reparations", body:"The TRC recommended financial and symbolic reparations; many victims felt these were too little and too late."},
    ],
    examples:[
      {title:"Amnesty conditions", body:"What did a perpetrator need to do to get amnesty?", answer:"Make a <strong>full disclosure</strong> of a crime that was <strong>politically motivated</strong>."},
      {title:"A success", body:"Give one success of the TRC.", answer:"It <strong>exposed the truth</strong> about many crimes and gave victims a public voice."},
      {title:"A criticism", body:"Give one criticism of the TRC.", answer:"<strong>Reparations were small and slow</strong>, and many perpetrators who didn't apply were never prosecuted."},
    ],
    mistakes:["Saying everyone who applied got amnesty.","Writing a one-sided essay — CAPS expects successes AND limitations.","Forgetting the three committees."],
    callout:{title:"Unfinished work", body:"Some families, such as those of the Cradock Four, have pushed for decades for prosecutions recommended after the TRC. Justice can be slow."},
    activity:"Write a paragraph answering: Was the TRC more about truth or about reconciliation? Use evidence.",
    activityAnswer:"A strong answer takes a position, uses evidence (public hearings, amnesty numbers, reparations, perpetrators who stayed silent) and acknowledges the other view.",
    examTip:"For “To what extent…” questions on the TRC, give a clear stand and balance evidence for and against.",
    keyterms:[{w:"TRC",d:"Truth and Reconciliation Commission"},{w:"Amnesty",d:"Freedom from prosecution for crimes"},{w:"Reparations",d:"Compensation or support for victims"}],
    quiz:[
      {q:"The TRC was chaired by:",opts:["Nelson Mandela","Desmond Tutu","Thabo Mbeki","F.W. de Klerk"],a:1,et:"Archbishop Desmond Tutu."},
      {q:"Amnesty required:",opts:["Paying a fine","Full disclosure of a politically motivated crime","An apology only","Leaving the country"],a:1,et:"Truth in exchange for amnesty."},
      {q:"About how many amnesty applicants received amnesty?",opts:["All of them","Fewer than 1 000 of about 7 000","Exactly half","None"],a:1,et:"Most applications were refused."},
    ],
    conclusion:"The TRC chose truth over revenge. It achieved a lot — and left work unfinished. Both parts belong in your essay."},

  4: {emoji:"🏗️", subtitle:"Grade 12 · Building a new South Africa",
    illusText:"The 1996 Constitution, signed at Sharpeville, is one of the most progressive in the world.",
    hook:{title:"A constitution for everyone", body:"Our <strong>Constitution</strong> protects the right to dignity, equality, education, housing and a clean environment — and it applies to everyone, including the government. Mandela signed it at Sharpeville on <strong>10 December 1996</strong>. Since then, South Africa has worked to undo apartheid's damage. Some changes have been dramatic; others have been slow."},
    intro:"After 1994, the government set out to transform society. The <strong>Constitution</strong> (1996, in force from February 1997) includes a <strong>Bill of Rights</strong> and established the Constitutional Court and Chapter 9 institutions such as the Public Protector. The <strong>Reconstruction and Development Programme (RDP)</strong> (1994) focused on housing, water, electricity and health; millions of homes were built and services extended. <strong>GEAR</strong> (1996) shifted towards economic growth and tight budgets. <strong>Employment equity</strong> and <strong>Black Economic Empowerment</strong> aimed to redress inequality in the workplace and economy. A social grant system grew to support millions of people.",
    concepts:[
      {t:"green", title:"📜 Rights and institutions", body:"The Bill of Rights, the Constitutional Court and Chapter 9 institutions protect democracy."},
      {t:"teal", title:"🏠 Delivery", body:"RDP houses, electricity, water and grants improved many lives, but backlogs remained."},
      {t:"gold", title:"📈 Economic policy", body:"RDP (needs-focused) gave way to GEAR (growth-focused) in 1996 — debated ever since."},
    ],
    examples:[
      {title:"RDP vs GEAR", body:"How did GEAR differ from the RDP?", answer:"The RDP focused on <strong>meeting basic needs</strong>; GEAR focused on <strong>economic growth, investment and controlling government spending</strong>."},
      {title:"Constitutional protection", body:"Name two Chapter 9 institutions.", answer:"The <strong>Public Protector</strong> and the <strong>Human Rights Commission</strong> (also the Auditor-General and Electoral Commission)."},
      {title:"Redress", body:"What is the aim of employment equity?", answer:"To <strong>redress past discrimination</strong> by promoting fair representation in the workplace."},
    ],
    mistakes:["Saying nothing has changed since 1994 — or that everything has been solved.","Mixing up RDP (1994) and GEAR (1996).","Forgetting the role of the Constitutional Court."],
    callout:{title:"The Constitution in action", body:"Court cases have used the Constitution to secure access to HIV treatment (TAC case, 2002) and housing rights (Grootboom case, 2000)."},
    activity:"Choose one right in the Bill of Rights. Find one way it has improved since 1994 and one way it is still not fully met.",
    activityAnswer:"Example: Education (section 29) — far more learners attend school and matric pass rates have risen; but many schools still lack libraries, labs and safe toilets.",
    examTip:"Evaluate transformation with evidence on both sides — achievements and ongoing challenges.",
    keyterms:[{w:"Bill of Rights",d:"Chapter 2 of the Constitution, listing everyone's rights"},{w:"RDP",d:"Reconstruction and Development Programme, 1994"},{w:"GEAR",d:"Growth, Employment and Redistribution strategy, 1996"}],
    quiz:[
      {q:"The Constitution was signed at:",opts:["Kliptown","Sharpeville","Robben Island","Soweto"],a:1,et:"10 December 1996."},
      {q:"The RDP focused mainly on:",opts:["Basic needs like housing and water","Military spending","Space exploration","Mining only"],a:0,et:"Launched in 1994."},
      {q:"GEAR was introduced in:",opts:["1990","1994","1996","2008"],a:2,et:"A growth-focused strategy."},
    ],
    conclusion:"Transformation is a long project. The Constitution set the destination; delivery has been uneven."},

  5: {emoji:"🔥", subtitle:"Grade 12 · Inequality, corruption and the fight for the promise of 1994",
    illusText:"#FeesMustFall in 2015 showed a new generation demanding the promise of 1994.",
    hook:{title:"#FeesMustFall", body:"In October 2015, university students across the country marched under the hashtag <strong>#FeesMustFall</strong>, demanding free, decolonised education. They forced a fee freeze and changed national debate. Like the students of 1976, a new generation was asking: why are the promises of freedom still not real for everyone? South Africa's challenges today are history in the making."},
    intro:"Post-apartheid South Africa faces serious challenges: <strong>inequality</strong> (one of the highest in the world), high <strong>unemployment</strong> (especially among young people), <strong>corruption</strong> — including <strong>state capture</strong>, investigated by the Zondo Commission (2018–2022) — <strong>service delivery protests</strong>, gender-based violence, crime, and outbreaks of <strong>xenophobic violence</strong> (notably in 2008). There are also signs of resilience: regular free elections, an independent judiciary, a free press, active civil society and peaceful changes of power. History helps us understand where these challenges come from.",
    concepts:[
      {t:"green", title:"📉 Inequality and unemployment", body:"Apartheid's legacy of unequal education, land and opportunity continues to shape who has jobs and wealth."},
      {t:"teal", title:"🕳️ Corruption", body:"State capture weakened institutions such as Eskom, Transnet and SARS — with real effects on electricity and services."},
      {t:"gold", title:"💪 Democratic strength", body:"Courts, the media, commissions and citizens have exposed wrongdoing — signs that democracy still works."},
    ],
    examples:[
      {title:"State capture", body:"What is state capture?", answer:"When <strong>private interests take control of state decisions and institutions</strong> for their own benefit."},
      {title:"Historical roots", body:"How does apartheid help explain unemployment today?", answer:"<strong>Bantu Education and spatial planning</strong> left many people with poor skills and far from jobs."},
      {title:"Democratic resilience", body:"Give one sign that South Africa's democracy is working.", answer:"<strong>Regular free elections</strong> and <strong>independent courts</strong> that have ruled against powerful people."},
    ],
    mistakes:["Blaming every problem only on the past, or ignoring the past completely.","Giving opinions without evidence.","Forgetting positive developments."],
    callout:{title:"You are history", body:"Your generation will decide how these challenges are met — through voting, work, activism and the choices you make."},
    activity:"Choose one challenge facing South Africa today. Write a paragraph explaining its historical roots and suggest one solution.",
    activityAnswer:"A strong answer links the challenge to specific history (e.g. Group Areas and Bantu Education for inequality), uses evidence, and offers a realistic solution (e.g. investment in early childhood education and skills).",
    examTip:"In essays linking past and present, show cause and continuity: “This challenge has roots in…, which still affects… because…”.",
    keyterms:[{w:"State capture",d:"Private interests controlling state institutions for their own benefit"},{w:"Xenophobia",d:"Hostility towards people from other countries"},{w:"Civil society",d:"Citizens' organisations outside government"}],
    quiz:[
      {q:"The commission that investigated state capture was the:",opts:["TRC","Zondo Commission","Marikana Commission","CODESA"],a:1,et:"2018–2022."},
      {q:"#FeesMustFall began in:",opts:["1976","1994","2015","2020"],a:2,et:"October 2015."},
      {q:"A sign of democratic strength is:",opts:["Independent courts","Banned newspapers","No elections","One-party rule"],a:0,et:"Courts can rule against the powerful."},
    ],
    conclusion:"Today's challenges have deep roots, and so does South Africans' determination to overcome them. History gives you the tools to understand both."},
};

